   118→// ChunkFileName returns the filename for a chunk at the given index.
   119→// Index 0 returns the base filename, index 1+ returns with chunk suffix.
   120→func ChunkFileName(baseName string, index int) string {
   121→	if index == 0 {
   122→		return baseName
   123→	}
   124→	return baseName + fmt.Sprintf(ChunkSuffix, index)
   125→}
   126→
   127→// ParseChunkIndex extracts the chunk index from a filename.
   128→// Returns 0 for the base file (no suffix), or the chunk number for suffixed files.
   129→// Returns -1 if the filename doesn't match the expected pattern.
   130→func ParseChunkIndex(filename, baseName string) int {
   131→	if filename == baseName {
   132→		return 0
   133→	}
   134→
   135→	if !strings.HasPrefix(filename, baseName+".") {
   136→		return -1
   137→	}
   138→
   139→	suffix := strings.TrimPrefix(filename, baseName+".")
   140→	var index int
   141→	if _, err := fmt.Sscanf(suffix, "%03d", &index); err != nil {
   142→		return -1
   143→	}
   144→	return index
   145→}
   146→
   147→// SortChunkFiles sorts chunk filenames in order (base file first, then numbered chunks).
   148→func SortChunkFiles(files []string, baseName string) []string {
   149→	sorted := make([]string, len(files))
   150→	copy(sorted, files)
   151→
   152→	sort.Slice(sorted, func(i, j int) bool {
   153→		idxI := ParseChunkIndex(sorted[i], baseName)
   154→		idxJ := ParseChunkIndex(sorted[j], baseName)
   155→		return idxI < idxJ
   156→	})
   157→
   158→	return sorted
   159→}
