   161→// geminiTranscriptDetect is used for detecting Gemini JSON format.
   162→type geminiTranscriptDetect struct {
   163→	Messages []interface{} `json:"messages"`
   164→}
   165→
   166→// DetectAgentTypeFromContent detects the agent type from transcript content.
   167→// Returns "Gemini CLI" if it appears to be Gemini JSON format, empty string otherwise.
   168→// This is used when the agent type is unknown but we need to chunk/reassemble correctly.
   169→func DetectAgentTypeFromContent(content []byte) string {
   170→	// Quick check: Gemini JSON starts with { and has a messages array
   171→	trimmed := strings.TrimSpace(string(content))
   172→	if !strings.HasPrefix(trimmed, "{") {
   173→		return ""
   174→	}
   175→
   176→	// Try to parse as Gemini JSON format (object with messages array)
   177→	var transcript geminiTranscriptDetect
   178→	if err := json.Unmarshal(content, &transcript); err != nil {
   179→		return ""
   180→	}
   181→
   182→	// Must have at least one message to be considered Gemini format
   183→	if len(transcript.Messages) > 0 {
   184→		return "Gemini CLI"
   185→	}
   186→
   187→	return ""
   188→}
